var i=(t,e)=>{let r=t.fields,o=s(r.templateId);return`project = ${t.projectKey}  AND ${o} is not EMPTY  AND issuetype = ${t.issueTypes.template} `+(e?` AND ${o} ~ "${n(e)}"`:"")},c=(t,e)=>{let r=(e??"").trim().toUpperCase();return`project = ${t.projectKey}  AND issuetype = ${t.issueTypes.template}  AND key = "${n(r)}"`},D=t=>i(t),l=t=>{let e=t.fields,r=s(e.templateId),o=s(e.templateStatus);return`project = ${t.projectKey}  AND ${r} is not EMPTY  AND issuetype = ${t.issueTypes.template}  AND (${o} ~ PUBLISHED OR ${o} ~ DEPRECATED)`},T=t=>{let e=t.fields,r=s(e.templateId);return`project = ${t.projectKey}  AND ${r} is not EMPTY  AND issuetype = ${t.issueTypes.template}  AND (creator = currentUser() OR assignee = currentUser() OR reporter = currentUser())`};function s(t){let e=(t??"").trim(),r=p.exec(e);return r?`cf[${r[1]}]`:e}function n(t){return(t??"").replace(/"/g,'\\"')}var p=/^customfield_(\d+)$/;export{i as a,c as b,D as c,l as d,T as e};
